namespace {
QJsonObject favourite(const QString &name,int tool,const QString &color,int width,bool dashed=false){QJsonObject o;o["name"]=name;o["tool"]=tool;o["color"]=color;o["width"]=width;o["dashed"]=dashed;return o;}
QIcon colourIcon(const QColor &colour,int tool,bool dashed){QPixmap image(32,32);image.fill(Qt::transparent);QPainter p(&image);p.setRenderHint(QPainter::Antialiasing);p.setPen(QPen(colour,tool==UBStylusTool::Marker?12:4,dashed?Qt::DashLine:Qt::SolidLine,Qt::RoundCap));p.drawLine(4,25,28,7);return QIcon(image);}
}
UBLessonTools::UBLessonTools(UBMainWindow *window):QObject(window),mWindow(window) {
    setObjectName("lessonTools");mHistory=new UBLessonHistory(this);
    auto add=[this](const QString &name,const QString &label,const QIcon &icon){auto a=new QAction(icon,label,mWindow);a->setObjectName(name);mWindow->boardToolBar->insertAction(mWindow->actionBoard,a);mWindow->addAction(a);return a;};
    for(int i=0;i<6;++i){auto a=add(QString("actionLessonFavourite%1").arg(i+1),QString(),QIcon());a->setShortcut(QKeySequence(QString("Ctrl+Alt+%1").arg(i+1)));a->setAutoRepeat(false);connect(a,&QAction::triggered,this,[this,i]{applyFavourite(i);});mFavouriteActions<<a;}
    refreshFavourites();
    auto edit=add("actionLessonFavourites",tr("Favourites…"),QIcon(":/images/teaching/favourites.svg"));connect(edit,&QAction::triggered,this,&UBLessonTools::editFavourites);
    auto cover=add("actionLessonCover",tr("Add cover"),QIcon(":/images/teaching/cover.svg"));cover->setShortcut(QKeySequence("Ctrl+Alt+C"));connect(cover,&QAction::triggered,this,[this]{addCover();});
    auto reveal=add("actionLessonReveal",tr("Reveal / cover"),QIcon(":/images/teaching/reveal.svg"));reveal->setShortcut(QKeySequence("Ctrl+Alt+R"));connect(reveal,&QAction::triggered,this,[this]{auto scene=UBApplication::boardController->activeScene();if(!scene)return;bool found=false;UBApplication::undoStack->beginMacro(tr("Reveal covers"));for(auto item:scene->selectedItems())if(auto svg=dynamic_cast<UBGraphicsSvgItem*>(item);svg&&svg->isLessonCover()){setCoverRevealed(svg,!isCoverRevealed(svg));found=true;}UBApplication::undoStack->endMacro();if(!found)manageCovers();});
    auto covers=add("actionLessonCovers",tr("Covers…"),QIcon(":/images/teaching/cover.svg"));connect(covers,&QAction::triggered,this,&UBLessonTools::manageCovers);
    auto versions=add("actionLessonHistory",tr("Versions…"),QIcon(":/images/teaching/history.svg"));versions->setShortcut(QKeySequence("Ctrl+Alt+H"));connect(versions,&QAction::triggered,this,&UBLessonTools::showHistory);
    auto save=add("actionLessonSaveVersion",tr("Save version"),QIcon(":/images/teaching/history.svg"));save->setShortcut(QKeySequence("Ctrl+Alt+S"));connect(save,&QAction::triggered,this,[this]{QString error;if(mHistory->checkpoint(true,&error))UBApplication::showMessage(tr("Lesson version saved."));else QMessageBox::warning(mWindow,tr("Save version"),error);});
    QList<QAction*> actions=mFavouriteActions;actions<<cover<<reveal<<versions<<save;UBShortcutManager::shortcutManager()->addActions(tr("Lesson tools"),actions,mWindow);
    if(mHistory->uncleanSessionDetected()&&!qApp->arguments().contains("--lesson-tools-test"))QTimer::singleShot(2000,this,[this]{if(QMessageBox::question(mWindow,tr("Recover lesson"),tr("LessonBoard did not close normally. Saved recovery copies are available. Review them now?"),QMessageBox::Yes|QMessageBox::No)==QMessageBox::Yes)showHistory();});
}
QJsonArray UBLessonTools::favourites() const {
    const auto bytes=UBSettings::settings()->value("LessonBoard/Favourites").toByteArray();auto values=QJsonDocument::fromJson(bytes).array();if(values.size()==6)return values;
    return {favourite(tr("Black thin"),UBStylusTool::Pen,"#000000",0),favourite(tr("Red pen"),UBStylusTool::Pen,"#d62828",1),favourite(tr("Blue pen"),UBStylusTool::Pen,"#1565c0",1),favourite(tr("Yellow highlight"),UBStylusTool::Marker,"#80ffff00",1),favourite(tr("Dashed line"),UBStylusTool::Line,"#000000",0,true),favourite(tr("Eraser"),UBStylusTool::Eraser,"#000000",1)};
}
bool UBLessonTools::saveFavourite(int slot,const QJsonObject &value) {
    const int tool=value.value("tool").toInt(-1);const auto color=QColor(value.value("color").toString());
    if(slot<0||slot>=6||!(tool==UBStylusTool::Pen||tool==UBStylusTool::Marker||tool==UBStylusTool::Line||tool==UBStylusTool::Eraser)||!color.isValid()||value.value("width").toInt(-1)<0||value.value("width").toInt()>2||value.value("name").toString().trimmed().isEmpty())return false;
    auto values=favourites();values.replace(slot,value);UBSettings::settings()->setValue("LessonBoard/Favourites",QJsonDocument(values).toJson(QJsonDocument::Compact));UBSettings::settings()->save();refreshFavourites();return true;
}
void UBLessonTools::refreshFavourites(){const auto values=favourites();for(int i=0;i<mFavouriteActions.size();++i){auto v=values[i].toObject();auto a=mFavouriteActions[i];a->setText(v.value("name").toString());a->setIcon(colourIcon(QColor(v.value("color").toString()),v.value("tool").toInt(),v.value("dashed").toBool()));a->setToolTip(tr("%1 — %2").arg(a->text(),a->shortcut().toString(QKeySequence::NativeText)));}}
bool UBLessonTools::applyFavourite(int slot){const auto values=favourites();if(slot<0||slot>=values.size())return false;auto v=values[slot].toObject();const int tool=v.value("tool").toInt();auto dc=UBDrawingController::drawingController();
    if(tool==UBStylusTool::Eraser)dc->setEraserWidthIndex(v.value("width").toInt());else{dc->setStylusTool(tool);dc->setLineWidthIndex(v.value("width").toInt());dc->setFavouriteColor(QColor(v.value("color").toString()));}
    const bool dashed=v.value("dashed").toBool();UBSettings::settings()->setValue("Teaching/DashedLines",dashed);if(auto dash=mWindow->findChild<QAction*>("actionTeachingDash"))dash->setChecked(tool==UBStylusTool::Line && dashed);mWindow->actionLine->setChecked(tool==UBStylusTool::Line && !dashed);return true;
}
void UBLessonTools::editFavourites(){QDialog dialog(mWindow);dialog.setWindowTitle(tr("Quick-access favourites"));auto layout=new QVBoxLayout(&dialog);auto form=new QFormLayout;auto slot=new QComboBox;for(const auto &v:favourites())slot->addItem(v.toObject().value("name").toString());auto name=new QLineEdit;form->addRow(tr("Favourite"),slot);form->addRow(tr("Name"),name);layout->addLayout(form);
    auto hint=new QLabel(tr("Choose a pen, highlighter, line or eraser, set its colour and width, then save that setup into a slot. Shortcuts: Ctrl+Alt+1 through Ctrl+Alt+6. Favourites keep their colours even if you change the palette."));hint->setWordWrap(true);layout->addWidget(hint);
    auto update=[=](int index){name->setText(favourites()[index].toObject().value("name").toString());};connect(slot,qOverload<int>(&QComboBox::currentIndexChanged),&dialog,update);update(0);
    auto save=new QPushButton(tr("Save current tool in this slot"));layout->addWidget(save);connect(save,&QPushButton::clicked,&dialog,[=,&dialog]{auto dc=UBDrawingController::drawingController();const int tool=dc->stylusTool();const int width=tool==UBStylusTool::Eraser?UBSettings::settings()->eraserWidthIndex():dc->currentToolWidthIndex();auto v=favourite(name->text().trimmed(),tool,dc->currentToolColor().name(QColor::HexArgb),width,UBSettings::settings()->value("Teaching/DashedLines",false).toBool());if(!saveFavourite(slot->currentIndex(),v)){QMessageBox::information(&dialog,tr("Choose a drawing tool"),tr("Select a pen, highlighter, line or eraser and give the favourite a name."));return;}slot->setItemText(slot->currentIndex(),v.value("name").toString());});auto buttons=new QDialogButtonBox(QDialogButtonBox::Close);layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.resize(500,260);dialog.exec();}
UBGraphicsSvgItem *UBLessonTools::addCover(){if(UBApplication::applicationController->displayMode()!=UBApplicationController::Board)UBApplication::applicationController->showBoard();auto board=UBApplication::boardController;auto scene=board->activeScene();if(!scene)return nullptr;
    const QByteArray data="<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"360\" height=\"160\" viewBox=\"0 0 360 160\"><metadata id=\"lessonboard-cover\">covered</metadata><rect x=\"2\" y=\"2\" width=\"356\" height=\"156\" rx=\"4\" fill=\"#334155\" stroke=\"#64748b\" stroke-width=\"2\"/></svg>";
    auto item=scene->addSvg(QUrl(),board->controlView()->mapToScene(board->controlView()->viewport()->rect().center()),data);if(item){if(mWindow->teachingTabs())mWindow->teachingTabs()->setCurrentIndex(0);mWindow->actionSelector->trigger();scene->clearSelection();item->setSelected(true);item->setZValue(2000000.0);}return item;
}
bool UBLessonTools::isCoverRevealed(UBGraphicsSvgItem *cover)const{return cover&&cover->isLessonCover()&&cover->fileData().contains(">revealed</metadata>");}
void UBLessonTools::setCoverRevealed(UBGraphicsSvgItem *cover,bool revealed){if(!cover||!cover->isLessonCover())return;QDomDocument doc;doc.setContent(cover->fileData());auto metadata=doc.elementsByTagName("metadata").at(0).toElement();while(!metadata.firstChild().isNull())metadata.removeChild(metadata.firstChild());metadata.appendChild(doc.createTextNode(revealed?"revealed":"covered"));auto rect=doc.elementsByTagName("rect").at(0).toElement();rect.setAttribute("fill",revealed?"none":"#334155");rect.setAttribute("stroke-dasharray",revealed?"8 5":"none");const auto before=cover->fileData();cover->setTeachingSvg(doc.toByteArray());cover->commitTeachingSvg(before);}
void UBLessonTools::manageCovers(){QDialog dialog(mWindow);dialog.setWindowTitle(tr("Page reveal covers"));auto layout=new QVBoxLayout(&dialog);auto info=new QLabel(tr("Unchecked covers hide the page. Check a cover to reveal it. Use the selection tool to move, resize or rotate covers."));info->setWordWrap(true);layout->addWidget(info);auto list=new QListWidget;layout->addWidget(list);QList<QPointer<UBGraphicsSvgItem>> covers;auto scene=UBApplication::boardController->activeScene();if(scene)for(auto item:scene->items())if(auto svg=dynamic_cast<UBGraphicsSvgItem*>(item);svg&&svg->isLessonCover()){covers<<svg;auto row=new QListWidgetItem(tr("Cover %1 — revealed").arg(covers.size()),list);row->setFlags(row->flags()|Qt::ItemIsUserCheckable);row->setCheckState(isCoverRevealed(svg)?Qt::Checked:Qt::Unchecked);}
    connect(list,&QListWidget::itemChanged,&dialog,[=](QListWidgetItem *row){const int index=list->row(row);if(index>=0&&index<covers.size()&&covers[index])setCoverRevealed(covers[index],row->checkState()==Qt::Checked);});auto buttons=new QDialogButtonBox(QDialogButtonBox::Close);layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.resize(450,300);dialog.exec();}
void UBLessonTools::showHistory(){QDialog dialog(mWindow);dialog.setWindowTitle(tr("Lesson recovery and version history"));auto layout=new QVBoxLayout(&dialog);auto info=new QLabel(tr("Recovery copies save every 20 seconds while you are not drawing. Versions are kept every 5 minutes when content changes, on exit, and with Save version. The latest recovery plus 50 versions per lesson are retained. Restore always opens a separate copy."));info->setWordWrap(true);layout->addWidget(info);auto lessons=new QComboBox;for(const auto &v:mHistory->documents()){auto d=v.toObject();lessons->addItem(d.value("name").toString(),d.value("id").toString());}layout->addWidget(lessons);auto list=new QListWidget;layout->addWidget(list);auto fill=[=]{list->clear();for(const auto &v:mHistory->versions(lessons->currentData().toString())){auto entry=v.toObject();const auto date=QDateTime::fromString(entry.value("created").toString(),Qt::ISODateWithMs).toLocalTime();auto item=new QListWidgetItem((entry.value("file").toString()=="recovery.json"?tr("Latest recovery — "):QString())+date.toString("yyyy-MM-dd HH:mm:ss"),list);item->setData(Qt::UserRole,entry.value("file").toString());}if(list->count())list->setCurrentRow(0);};connect(lessons,qOverload<int>(&QComboBox::currentIndexChanged),&dialog,[fill](int){fill();});auto current=UBApplication::boardController->selectedDocument();if(current){const int index=lessons->findData(current->uuid().toString(QUuid::WithoutBraces));if(index>=0)lessons->setCurrentIndex(index);}fill();
    if(!mHistory->lastError().isEmpty())layout->addWidget(new QLabel(mHistory->lastError()));auto restore=new QPushButton(tr("Restore selected version as a new lesson"));restore->setEnabled(list->count()>0);connect(list,&QListWidget::currentRowChanged,restore,[restore](int index){restore->setEnabled(index>=0);});layout->addWidget(restore);connect(restore,&QPushButton::clicked,&dialog,[=,&dialog]{if(!list->currentItem())return;QString error;auto copy=mHistory->restoreCopy(lessons->currentData().toString(),list->currentItem()->data(Qt::UserRole).toString(),&error);if(!copy){QMessageBox::warning(&dialog,tr("Cannot restore version"),error);return;}UBApplication::boardController->setActiveDocumentScene(copy,0);UBApplication::applicationController->showBoard();dialog.accept();});auto buttons=new QDialogButtonBox(QDialogButtonBox::Close);layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.resize(600,420);dialog.exec();}
